  insert into public.brands (name, website, description, country, status) values ('Stylevana', 'https://www.stylevana.com', 'Hong Kong-based Asian beauty and fashion retailer running its own VANA Family (VANATeam) Creator Program on its own site: creators get a unique discount code, earn commission on every sale made with it, progress through Glow/Radiance/Vibrance/Aurora tiers, receive a free Welcome Box of best-selling K-beauty products, and cash out via PayPal at a US$30 threshold.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'beauty'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'In-house (VANA Family Creator Program, own site)', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.stylevana.com/en_US/creators/view/join.', 'https://www.stylevana.com/en_US/creators/view/join', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Stylevana VANA Family Creator Program', 'https://www.stylevana.com/en_US/creators/view/join', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.stylevana.com/en_US/creators/view/join', 'brand_site', 'affiliate_program', 'STYLEVANA''s official VANA Family join page describes its own Influencer/Creator Program: applicants need an active public TikTok, Instagram or YouTube account; creators receive a unique discount code and earn commission on every sale made with it across four tiers (Glow, Radiance, Vibrance, Aurora), each displaying a 5% commission rate on returning-customer orders; commissions are redeemed monthly via PayPal once earnings reach US$30, and new creators can claim a free Welcome Box of K-beauty products. The program''s own Terms & Conditions state the exact commission percentage is not fixed: it is dynamic, set by creator tier and by new-vs-returning order type, and shown in the creator dashboard.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.stylevana.com/en_US/creators/view/join', 'brand_site', 'commission_cap', 'The official program FAQ answers the earnings-limit question directly: ''Is there a maximum amount I can earn? No, there is no maximum limit on how much you can earn through our Creator Program... allowing for limitless potential!'' — an explicit no-cap statement on the brand''s own page, so commission_cap is recorded as uncapped. Separately, the US$100/month maximum on the page applies only to creator-referral bonuses (US$10 per referred creator), not to sales commission. No absolute creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/stylevana-us/', 'directory', 'commission_rate_conflict', 'Third-party figures for Stylevana''s separate network affiliate listings conflict with each other and with the creator program''s dynamic structure: Lasso lists a Stylevana (US) affiliate program at 10% with a 60-day cookie, LinkApprove reports about 2.7% on a 30-day cookie, and Shopper lists up to 5%. Because the brand''s own terms state the creator-program rate is not fixed and directory figures conflict, commission_rate is recorded as null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 15, 10, 9, 4, '{"compensation": "Earnings are explicitly uncapped in the brand''s own FAQ, but the commission percentage is dynamic and unsettleable from published sources (rate null), which keeps compensation below top tier.", "contact_access": "Full program page, FAQ and terms on the brand''s own domain with self-serve sign-up; no public partnerships email.", "credibility": "Large, long-running Asian beauty retailer (founded 2015 era, global storefronts) with complete published program terms.", "niche_fit": "One of the biggest K-beauty/Asian beauty storefronts \u2014 thousands of skincare and makeup products of UGC material.", "opportunity_availability": "Open enrollment with code activation in about 4 hours; requires a public TikTok, Instagram or YouTube account and a PayPal-supported country.", "ugc_evidence": "A dedicated creator program built for social creators: discount codes, tier progression, free Welcome Box product, a creator dashboard and an explicit content-posting framework."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Kossma Beauty', 'https://kossma.com', 'US indie ''PUFA-aware'' clean skincare brand (formulated without high-PUFA seed oils or essential oils, with an 80% return-customer rate claimed on its own site) running its own affiliate program: 20% commission on every sale, with digital marketing assets, sales and story-selling education, a private affiliate community and marketing-team support.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'In-house (own program)', 20, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://kossma.com/pages/affiliates.', 'https://kossma.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kossma Beauty Affiliate Program', 'https://kossma.com/pages/affiliates', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kossma.com/pages/affiliates', 'brand_site', 'affiliate_program', 'Kossma''s official Affiliates page states affiliates earn 20% commission on every sale they generate, and lists the program benefits: digital marketing assets and ready-to-use content, sales and social media education, story-selling and email marketing training, access to a private affiliate community, and ongoing support from the Kossma marketing team. The page also cites an 80% return customer rate and thousands of customer reviews as social proof.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://kossma.com/pages/affiliates', 'brand_site', 'commission_cap', 'The brand''s affiliate page contains no statement about an earnings cap or limit, so commission_cap is recorded as unknown (not uncapped). No creator counts are published, so creator_saturation stays unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 17, 9, 8, 3, '{"compensation": "A clean, high 20% on every sale published on the brand''s own page; no cap statement, so not top-scored.", "contact_access": "Program page and sign-up on the brand''s own site; no public email.", "credibility": "Small indie brand; loyalty claims (80% return rate) are the brand''s own and unverified independently.", "niche_fit": "Distinctive clean-skincare angle (PUFA-aware, tallow-inclusive formulas) that gives creators a fresh story in a repetitive niche.", "opportunity_availability": "Program page is live and recruiting; approval process and cookie terms are not published.", "ugc_evidence": "Program supplies ready-to-use content, story-selling training and a private community \u2014 creator-oriented, though framed for affiliates generally rather than UGC specifically."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Wishtrend', 'https://www.wishtrend.com', 'Korean beauty retailer (home of Dear, Klairs, I''m From and By Wishtrend) running its own affiliate program: two independent affiliate directories agree on a 12% commission with a long 60-day cookie, aimed at skincare bloggers and K-beauty creators.', null, 'published') returning id into bid;
