  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://amalinkspro.com/best-affiliate-programs-beginners/wishtrend/', 'directory', 'affiliate_program', 'AmalinksPro''s Wishtrend listing independently reports the same terms — 12% commission per sale and a 60-day cookie — corroborating the rate. No source publishes an earnings-cap statement (cap unknown) or absolute creator counts (saturation unknown).', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 15, 8, 8, 4, '{"compensation": "Solid 12% with an unusually long 60-day cookie, corroborated by two directories; no cap statement published.", "contact_access": "No public partnerships email or official program page surfaced; enrollment is via the brand''s own program route.", "credibility": "Established K-beauty retailer and brand owner (Dear, Klairs, By Wishtrend) with a long operating history.", "niche_fit": "Curated K-beauty skincare retailer \u2014 core UGC territory for routine and ingredient content.", "opportunity_availability": "Program is listed as live by two directories; approval terms are not published.", "ugc_evidence": "Program is used by skincare bloggers per directory reporting; no dedicated creator/UGC offer is published by the brand."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PRAI Beauty', 'https://praibeauty.com', 'Pro-aging skincare brand for women over 50 (HSN-born, known for neck and décolletage care) running its affiliate program on Awin: the network''s own merchant profile publishes a 10% base commission, explicitly welcomes content creators and influencers, and names a partnerships contact for custom opportunities.', null, 'published') returning id into bid;
