  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/100463/commission-groups.', 'https://ui.awin.com/merchant-profile/100463/commission-groups', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'PRAI Beauty Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/100463/commission-groups', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/100463/commission-groups', 'affiliate_network', 'affiliate_program', 'Awin''s merchant profile for the PRAI Beauty (US) affiliate program publishes the commission structure: 10% base commission on all eligible sales (full-priced products and value bundles/sets; not gift cards, shipping or taxes), with higher tiers for strong performance and new-customer volume, exclusive codes for select partners, and commission boosts during promotional windows. The profile states ''We''re excited to partner with content creators, editorial publishers, loyalty partners, and performance affiliates'' and names amanda@ptrnbrands.com for custom opportunities. Applications are reviewed and can be declined.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/68816', 'affiliate_network', 'affiliate_program', 'Awin''s PRAI Beauty UK merchant profile publishes a regional rate card — baseline 5%, content/editorial/blogger/influencer affiliates 8%, voucher-code affiliates 1%, cashback 3% — confirming the program actively courts influencer affiliates; the US profile''s 10% base is the rate recorded for this US-focused directory. Neither profile publishes an earnings-cap statement (cap unknown) or creator counts (saturation unknown).', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 14, 12, 8, 4, '{"compensation": "Published 10% base on the network''s own profile with higher tiers and boost windows; no cap statement.", "contact_access": "A named partnerships email is published on the Awin profile for custom opportunities \u2014 rare direct access.", "credibility": "HSN-built brand with a loyal mature-skincare customer base and published network terms.", "niche_fit": "Focused pro-aging skincare (neck/firming hero products) \u2014 a defined, underserved UGC niche (50+ creators).", "opportunity_availability": "Program live on Awin with published terms; applications are reviewed and may be declined for brand fit.", "ugc_evidence": "The Awin profile explicitly recruits content creators and influencers and offers exclusive codes and custom landing pages on request."}'::jsonb);
