  insert into public.brands (name, website, description, country, status) values ('YesStyle', 'https://www.yesstyle.com', 'One of the largest online Asian beauty and fashion retailers (800+ beauty brands, 11M+ monthly customers per its Awin profile) running its affiliate program on Awin with a published tiered commission structure — maximum 10% for social influencers and review/content sites, 15% for invitation-only KOLs — plus a separate in-house influencer code program.', null, 'published') returning id into bid;
