  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'YesStyle Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/63156', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/63156', 'affiliate_network', 'affiliate_program', 'Awin''s official merchant profile for the YesStyle Affiliate Program publishes the full commission structure: KOL (invitation-only) maximum 15%; Social Influencers maximum 10%; Review Sites maximum 10%; Blogs and Content Sites maximum 10%; sub-affiliate networks maximum 5%; cashback/coupon sites maximum 2% (new customers only). The profile also publishes a 30-day cookie period, a product feed and creatives, and a weekly affiliate newsletter. Because the published figures are category maxima rather than a single rate, commission_rate is recorded as null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/yesstyle-us-global/', 'directory', 'commission_rate_conflict', 'Directory figures for YesStyle vary widely — Lasso lists 1.6% per sale and LinkApprove about 1% — reflecting realized blended rates rather than the Awin profile''s category maxima; neither matches a single publishable rate, reinforcing the null recording. No source publishes an earnings-cap statement (cap unknown) or absolute creator counts (saturation unknown).', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 10, 9, 8, 5, '{"compensation": "Only category maxima are published (influencers up to 10%) and realized directory figures are far lower, so the rate is honestly null.", "contact_access": "Application via the Awin merchant profile; no public partnerships email.", "credibility": "One of the largest Asian beauty retailers globally, operating since 2006 per its Awin profile.", "niche_fit": "800+ Asian beauty brands in one storefront \u2014 endless K-beauty haul and review material.", "opportunity_availability": "Program live on Awin with a published 30-day cookie; the top KOL tier is invitation-only.", "ugc_evidence": "The Awin structure has a dedicated Social Influencers category, and the retailer also runs an influencer code program \u2014 direct creator routes exist."}'::jsonb);
