  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://whopaysinfluencers.com/brands/beauty/', 'directory', 'affiliate_program', 'WhoPaysInfluencers'' makeup ambassador listing records Fenty Beauty''s route as ''Brand Ambassador (affiliate sign-up via Rakuten Advertising)'' with no rate published by the brand.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/category/beauty-skincare', 'directory', 'commission_rate_conflict', 'Published Fenty Beauty rates conflict: LinkApprove lists 8% per sale with a 30-day cookie, CommissionDex''s Rakuten listing reports 5-8%, Brandid reports about 5%, and UpPromote''s directory reports a 4-10% range depending on network. Because the figures conflict and the brand publishes none, commission_rate is recorded as null. No source publishes an earnings-cap statement (cap unknown) or absolute creator counts (saturation unknown).', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 11, 9, 8, 7, 5, '{"compensation": "Published rates conflict across directories (about 5-8%, wider ranges by network) and the brand publishes none, so the rate is null.", "contact_access": "Application and management via the Rakuten dashboard; no public partnerships email found.", "credibility": "LVMH/Kendo flagship brand founded by Rihanna; maximum brand credibility and cultural pull.", "niche_fit": "Shade-inclusive complexion and viral color products \u2014 a core beauty UGC fit across demographics.", "opportunity_availability": "Program live on Rakuten; terms vary by network and region and approval is at the brand''s discretion.", "ugc_evidence": "An established network affiliate program used by beauty publishers; no dedicated UGC offer published by the brand."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Elemis', 'https://www.elemis.com', 'British premium skincare brand (Pro-Collagen range, spa heritage, owned by the L''Occitane Group) with affiliate listings through Sovrn Commerce and its own Skinsiders social affiliate program — an application-based creator community built into its website, powered by Duel, with personal codes and always-on commission.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'skincare'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Sovrn Commerce', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://merchants.sovrn.com/merchants/80048/elemis-com-affiliate-program.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Elemis Affiliate Program (Sovrn) + Skinsiders Social Affiliate Program', null, null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/80048/elemis-com-affiliate-program', 'affiliate_network', 'affiliate_program', 'Sovrn Commerce''s merchant page for elemis.com confirms an affiliate program with a 30-day cookie; specific commission details are available only inside the Sovrn dashboard after joining.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.duel.tech/case-studies/elemis', 'directory', 'creator_program', 'Duel''s case study describes ELEMIS''s own Skinsiders social affiliate program: an exclusive, application-based program built into the ELEMIS website where members create and share content for rewards, with a tiered gamified system, personal codes and always-on commission opportunities; it reports 2,120 program members and GBP 261k referral revenue from Nov 2022 to Sep 2023. A member base in the thousands is far above the ~100-creator low-saturation bar, so creator_saturation stays unknown rather than low.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/category/beauty-skincare', 'directory', 'commission_rate_conflict', 'Published Elemis rates conflict: LinkApprove lists up to 10% per sale, Lasso lists up to 15%, Shopper lists 5-10%, and Lasso''s AU listing reports 7%. Because the figures conflict and neither the brand nor Sovrn publishes one, commission_rate is recorded as null. No source publishes an earnings-cap statement (cap unknown).', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 9, 8, 7, 5, '{"compensation": "Published rates conflict across every listing (5-15%) and no official figure exists, so the rate is null.", "contact_access": "Access via the Sovrn dashboard or the on-site Skinsiders application; no public partnerships email found.", "credibility": "L''Occitane Group premium brand with decades of spa and retail history.", "niche_fit": "Premium anti-aging skincare staples (cleansing balm, Pro-Collagen) \u2014 strong routine and review content fit.", "opportunity_availability": "Network program live on Sovrn; the Skinsiders creator program is application-based and selective.", "ugc_evidence": "Skinsiders is a purpose-built social affiliate program for content creators with personal codes and tiered rewards \u2014 direct UGC evidence, though its reported 2,120 members rule out a low-saturation claim."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('World Nomads', 'https://www.worldnomads.com', 'Travel insurance brand built for adventurous travellers, covering 150+ adventure activities with policies that can be bought even after a trip has started. Its own Partners Network pays affiliates 10% for every referred insurance sale and states explicitly that earnings are not capped, with a 60-day cookie and monthly payments.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://partner.worldnomads.com/partnerpublic/frequently-asked-questions.', 'https://partner.worldnomads.com/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'World Nomads Partners Network', 'https://partner.worldnomads.com/', 'https://partner.worldnomads.com/partnerpublic/frequently-asked-questions', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partner.worldnomads.com/partnerpublic/frequently-asked-questions', 'official_program_page', 'affiliate_program', 'Official Partners Network FAQ, ''How much commission will I earn?'': ''As an affiliate you will receive 10% for every sale that you refer to us. We don''t cap your earnings so how much you make is completely up to you.''', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partner.worldnomads.com/partnerpublic/frequently-asked-questions', 'official_program_page', 'affiliate_program', 'Program mechanics on the official FAQ: applications are assessed within 5 working days; a unique affiliate code sets a 60-day cookie; partners are paid monthly by PayPal or bank transfer once the balance reaches the $250 minimum threshold; the FAQ notes the network has more than 3,000 partners.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://atlas.hellosafe.com/travel-insurance-affiliate-program/best-programs/', 'third_party_directory', 'affiliate_program', 'Third-party comparisons report a much larger affiliate footprint (one cites 13,000+ affiliates) and a separate CJ channel paying $0.83 per lead/quote instead of 10% of sale; the 10% uncapped terms recorded here are the brand''s own Partners Network terms, and with partner counts in the thousands the saturation is not low, so it stays unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 15, 16, 5, 8, 5, '{"compensation": "10% of every referred sale with an explicit ''We don''t cap your earnings'' statement on the brand''s own FAQ; held below maximum because the payout threshold is a high $250.", "contact_access": "No partnerships email is published on the partner pages; contact runs through the partner account after application.", "credibility": "One of the longest-running travel-insurance affiliate programs (operating since the early 2000s) with fully published partner terms on its own partner site.", "niche_fit": "Adventure-travel insurance is a natural, repeatable recommendation for travel creators, and policies can even be bought mid-trip.", "opportunity_availability": "Open online application on the partner site, assessed within 5 working days.", "ugc_evidence": "The program is built around referral links and supplied content for partner websites and is widely used by travel bloggers; partner counts are in the thousands, so saturation is not low and stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tiqets', 'https://www.tiqets.com', 'Booking platform for museums, attractions and experiences worldwide, run by Amsterdam-based Tiqets International B.V. Its affiliate program on Awin pays commission on the total booking value - 6% for content sites - with a 30-day cookie and a published affiliate support email.', 'Netherlands', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'awinpartners@tiqets.com', null, 'https://ui.awin.com/merchant-profile/12428?setLocale=sv_SE', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 6, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/12428?setLocale=sv_SE.', 'https://ui.awin.com/merchant-profile/12428?setLocale=sv_SE', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tiqets Affiliate Program (Awin)', 'https://ui.awin.com/merchant-profile/12428?setLocale=sv_SE', 'https://ui.awin.com/merchant-profile/12428?setLocale=sv_SE', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/12428?setLocale=sv_SE', 'network_profile', 'affiliate_program', 'Tiqets'' own Awin merchant profile: commission is calculated on the total booking value - Voucher/Coupon sites 4%, Cashback sites 5%, Other sites 6% - with a 30-day cookie; a small set of named products (e.g. a Colosseum reserved-entrance product) is fixed at 3%, and Europa Park pays no cashback commission.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/12428?setLocale=sv_SE', 'network_profile', 'affiliate_program', 'The Awin profile publishes a direct support contact for affiliates: ''The email awinpartners@tiqets.com is available to support you for any demands, needs, or issues you encounter with us.'' No earnings-cap statement appears on the profile, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.travelpayouts.com/blog/tiqets-affiliate-program/', 'third_party_directory', 'affiliate_program', 'A separate Travelpayouts channel lists Tiqets at 8% of the booking price, which differs from the 6% content-site rate on the brand''s own Awin profile; the Awin profile rate is the one recorded here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 11, 11, 8, 5, '{"compensation": "6% of total booking value for content sites via Awin (4-5% for voucher/cashback, a few products fixed at 3%); no cap statement is published, so the cap is unknown.", "contact_access": "A named affiliate support email (awinpartners@tiqets.com) is published on the brand''s Awin profile.", "credibility": "Established global attractions platform running a documented program on Awin, a major network, with written partner terms.", "niche_fit": "Museum and attraction tickets in cities worldwide slot directly into travel itineraries and city-guide content.", "opportunity_availability": "Joinable through the Awin merchant profile; the brand reviews applications and not all sites are accepted.", "ugc_evidence": "The program recruits content publishers across blogs, social media and newsletters; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Peek Apparel', 'https://peek-apparel.com', 'Fitness apparel brand whose creator program, Beyond Peek, pays fitness creators a starting 10% commission that climbs through six permanent tiers to 30% as their ''Momentum'' grows. The program is free to join, pays monthly, lets creators cash out from $10, and provides a personal discount code, dashboard and creative kit.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fitness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://beyond.peek-apparel.com/.', 'https://beyond.peek-apparel.com/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Beyond Peek Creator Program', 'https://beyond.peek-apparel.com/', 'https://beyond.peek-apparel.com/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beyond.peek-apparel.com/', 'official_program_page', 'creator_program', 'Official program page: ''Peek pays fitness creators up to 30% on every sale, and your rate climbs as you do. Permanent tiers, monthly payouts, no quotas.'' The six published tiers are Affiliate 10%, Advocate 14%, Insider 18%, Leader 22%, Partner 26% and Visionary 30%, earned on ''Momentum'' and never reset; joining costs $0 and cash-out starts at $10.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beyond.peek-apparel.com/', 'official_program_page', 'creator_program', 'Program mechanics on the official page: creators claim a personal discount code, share it in posts, stories and link-in-bio, and track every sale, commission and payout in a live wallet/dashboard with a kit of ready creatives; Insider tier and above includes a full kit refresh every season.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beyond.peek-apparel.com/', 'official_program_page', 'affiliate_program', 'No earnings-cap statement is published anywhere on the program page - its ''no quotas'' wording is about posting quotas, not an earnings limit - so the commission cap is recorded as unknown rather than inferred from the 30% top tier.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 18, 15, 4, 8, 3, '{"compensation": "10% starting commission rising permanently to 30% at the top tier, with monthly payouts and a low $10 cash-out; no cap statement is published, so the cap is unknown.", "contact_access": "No email or named contact is published on the program page; everything runs through the creator dashboard.", "credibility": "A young, small apparel brand; the program terms are fully published on its own portal, but there is little independent track record.", "niche_fit": "Training apparel made for fitness creators to wear and demo in their own workout content.", "opportunity_availability": "Open self-serve signup on the program portal with a code issued after a quick uniqueness check.", "ugc_evidence": "The program is explicitly built for fitness creators - personal codes for posts and stories, a creative kit and seasonal kit refreshes; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Civitatis', 'https://www.civitatis.com', 'Madrid-based marketplace for guided tours, activities, excursions and airport transfers in major cities worldwide, serving over 11.2 million customers a year. Its in-house affiliates programme pays 8-10% commission depending on monthly sales volume, plus a fixed EUR 1 per free-tour participant, and deliberately runs without affiliate networks.', 'Spain', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 8, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.civitatis.com/en/affiliates/.', 'https://www.civitatis.com/en/affiliates/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Civitatis Affiliates Programme', 'https://www.civitatis.com/en/affiliates/', 'https://www.civitatis.com/en/affiliates/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.civitatis.com/en/affiliates/', 'official_program_page', 'affiliate_program', 'Official affiliates FAQ: ''We offer between 8% and 10% commission on each sale, depending on the monthly volume of sales. And we offer a fixed commission of EUR 1 per free tour participant.'' Commission is paid monthly on the previous month''s completed activities, via bank transfer or PayPal; average sale is over EUR 100.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.civitatis.com/en/affiliates/affiliate-program-general-conditions/', 'official_program_page', 'affiliate_program', 'The programme''s General Conditions set the volume tiers: 8% on monthly sales under EUR 1,000, 9% from EUR 1,000 to 5,000, and 10% above EUR 5,000, recalculated monthly; the affiliates page adds a 30-day cookie and states ''we don''t work with intermediates or affiliation networks'' - the programme is brand-direct only. No earnings-cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.civitatis.com/en/affiliates/', 'official_program_page', 'creator_program', 'Eligibility caveat on the official page: ''To take part in our affiliates programme you must have a web page or blog related in some way to travel... We currently don''t work with partners who rely solely on social networks.'' Affiliates get a dedicated affiliates team, widgets, banners and an optional API.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 12, 13, 7, 7, 5, '{"compensation": "8% starting commission rising to 10% at higher monthly volumes, plus EUR 1 per free-tour participant, on an average sale above EUR 100; no cap statement is published, so the cap is unknown.", "contact_access": "A dedicated affiliates team supports partners and API questions go through the site, but no direct partnerships email is published on the page.", "credibility": "Market leader in Spanish-language tours with 10+ years operating, 11.2 million customers a year and full written programme conditions.", "niche_fit": "Tours, activities and transfers in destinations worldwide - especially strong for Spanish- and European-focused travel content.", "opportunity_availability": "Free validated registration, but applicants must have a functioning travel website or blog; social-only creators are not accepted.", "ugc_evidence": "Widgets, banners, photos, videos and an API are supplied for partner sites; the website/blog requirement limits pure social creators, and no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Holafly', 'https://esim.holafly.com', 'International eSIM provider offering unlimited-data plans in more than 200 destinations, rated 4.7/5 across 119,768+ Trustpilot reviews. Its affiliate program is aimed at travel creators, offers commissions on every sale plus free product, and reports more than 3,500 affiliate partners; the program runs through major networks including Impact.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://esim.holafly.com/affiliate-program/.', 'https://esim.holafly.com/affiliate-program/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Holafly Affiliate Program', 'https://esim.holafly.com/affiliate-program/', 'https://esim.holafly.com/affiliate-program/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://esim.holafly.com/affiliate-program/', 'official_program_page', 'creator_program', 'Official affiliate page (''Conquer the World with your Creativity''): affiliates ''earn commissions on every sale'' and get free Holafly products, SEO and social-media guidance and real-time sales monitoring; the page shows ''+3500 affiliate partners'' and the brand''s 4.7/5 rating from 119,768+ Trustpilot reviews - but it publishes no commission percentage and no cap statement.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://affiliateprogramsguru.com/programs/holafly-affiliate-program/', 'third_party_directory', 'affiliate_program', 'Third-party directories report a 10% base commission (up to 20% for top performers) across Impact, Awin and ShareASale with a 30-day cookie, while other roundups cite up to 15% via an influencer network; because the brand''s own page publishes no rate and the third-party figures differ by channel, commission_rate is recorded as null and the cap as unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 16, 8, 4, 8, 5, '{"compensation": "The official page publishes no rate and third-party figures conflict by channel (10% base reported, up to 15-20% for top performers), so compensation scores low until terms are confirmed inside the network; cap unknown.", "contact_access": "No email is published on the affiliate page; contact runs through the network application and the affiliate platform.", "credibility": "One of the largest travel eSIM brands, with 200+ destinations and a 4.7/5 rating from 119,768+ Trustpilot reviews cited on its own page.", "niche_fit": "Travel data is a pain point every international travel creator''s audience has, and eSIM setup makes easy how-to content.", "opportunity_availability": "Applications run through Impact and other major networks linked from the brand''s affiliate page.", "ugc_evidence": "The program page is written for creators, with featured affiliate stories, free product and social-media guidance; its own 3,500+ partner count is far above low saturation, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Airzen', 'https://airzen.com', 'Australian travel eSIM company selling prepaid mobile data for 200+ countries and regions, installed by QR code before flying. Its Affiliate Program for Travel Creators states in its FAQ that there is no cap on earnings, with a 30-day tracking cookie and PayPal payouts after a short refund window.', 'Australia', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'travel'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://airzen-staging.airzen.com/affiliate-program.', 'https://airzen-staging.airzen.com/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Airzen Affiliate Program for Travel Creators', 'https://airzen-staging.airzen.com/affiliate-program', 'https://airzen-staging.airzen.com/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://airzen-staging.airzen.com/affiliate-program', 'official_program_page', 'affiliate_program', 'The brand''s affiliate program FAQ answers ''How much commission can I earn?'' with: ''There''s no cap on your earnings - the more travellers you refer, the more you earn, calculated on the value of each order.'' Caveat: the program page was fetched on the brand''s staging subdomain (airzen-staging.airzen.com, using the brand''s own CDN assets), so the terms should be re-confirmed on the live portal at application.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://airzen-staging.airzen.com/affiliate-program', 'official_program_page', 'affiliate_program', 'The same page conflicts on the rate: its perks section states ''Base Commission: 15% per sale'' and ''High Volume Commission: Up to 20% for top performers'', while the FAQ says ''Commissions start at 10%, and your exact rate is shown in your affiliate dashboard.'' Because the page does not settle one starting rate, commission_rate is recorded as null.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://airzen-staging.airzen.com/affiliate-program', 'official_program_page', 'creator_program', 'Program mechanics on the page: open to ''travel bloggers, content creators, website owners, social media influencers and everyday travellers'' worldwide with no large audience required; applications are reviewed by the team; tracking uses a 30-day cookie; commissions are held about 7 days for refunds, then paid to the affiliate''s PayPal account; the page describes Airzen as ''an Australian travel eSIM company'' covering 200+ countries and regions.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 13, 4, 8, 2, '{"compensation": "An explicit ''There''s no cap on your earnings'' FAQ answer, but the page conflicts on the starting rate (10% in the FAQ vs a 15% base in the perks section), so the rate is unrecorded and compensation scores mid-range.", "contact_access": "No email is published; the FAQ directs questions to the brand''s contact page and support team.", "credibility": "A small Australian eSIM brand, and the program page was served from its staging subdomain - terms are detailed but should be re-confirmed on the live portal before relying on them.", "niche_fit": "Prepaid travel data for 200+ countries is a staple recommendation for travel creators, with QR-code setup that demos well on camera.", "opportunity_availability": "Free application through the brand''s affiliate portal, open worldwide with no minimum audience.", "ugc_evidence": "The program is written specifically for travel creators and influencers, with a referral link, optional coupon code, real-time dashboard and brand assets; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Tecovas', 'https://www.tecovas.com', 'Austin, Texas-based western brand handcrafting cowboy boots, western apparel and accessories, sold direct to consumer. Its affiliate program runs on Impact with banners, text links and product feeds, a 30-day cookie and payment once commissions reach $50; network listings put the rate at 10% per sale.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 10, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.tecovas.com/p/affiliate-program.', 'https://www.tecovas.com/p/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Tecovas Affiliate Program (Impact)', 'https://www.tecovas.com/p/affiliate-program', 'https://www.tecovas.com/p/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tecovas.com/p/affiliate-program', 'official_program_page', 'affiliate_program', 'Official affiliate page: ''Tecovas has partnered with Impact, the leader in affiliate technology, to provide you a robust affiliate program for your website.'' Benefits listed: free signup, competitive commission, 30-day cookie, 30-day returns and high average order value; ''Payment will be made through Impact once your account has reached $50 or more in commissions.'' The page does not print the percentage itself and publishes no cap statement, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/tecovas/', 'third_party_directory', 'affiliate_program', 'LinkClicky''s network listing for the program records the Tecovas offer on Impact at 10% per sale; Sovrn''s merchant page describes Tecovas as an Austin, Texas-based western footwear and lifestyle brand founded in 2015.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 13, 4, 8, 5, '{"compensation": "10% per sale per the program''s network listing, on premium boots with a high average order value; the brand''s own page calls the commission ''competitive'' without printing it, and no cap statement is published, so the cap is unknown.", "contact_access": "No email is published on the affiliate page; application and contact run through Impact.", "credibility": "Established direct-to-consumer western brand founded in 2015, running its program on Impact, a major network.", "niche_fit": "Handmade cowboy boots and western wear are distinctive, demonstrable products for western, country-lifestyle and menswear creators.", "opportunity_availability": "Free signup through the Impact link on the official page.", "ugc_evidence": "The program supplies banners, text links and product feeds for partner websites; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('True Classic', 'https://www.trueclassictees.com', 'Fast-growing direct-to-consumer menswear brand known for fitted t-shirts and everyday basics. It runs affiliate programs through major networks - CJ Affiliate in the US and an Awin programme in the UK that pays 20% on new customers - aimed at publishers, bloggers and content creators, though published rates differ sharply by channel and region.', null, 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'affiliates@fairforecast.com', null, 'https://ui.awin.com/merchant-profile/116647?setLocale=pl_PL', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate / Awin', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/116647?setLocale=pl_PL.', 'https://ui.awin.com/merchant-profile/116647?setLocale=pl_PL', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'True Classic Affiliate Program', 'https://ui.awin.com/merchant-profile/116647?setLocale=pl_PL', 'https://ui.awin.com/merchant-profile/116647?setLocale=pl_PL', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/116647?setLocale=pl_PL', 'network_profile', 'affiliate_program', 'True Classic''s own Awin merchant profile for the UK programme: the program ''is ideal for publishers, CSS partners, bloggers, content creators, and cashback or voucher platforms'', with ''performance-based payouts'' of 20% on new customers and 0.5% on existing customers; coupon/discount sites are not accepted; questions and custom campaigns go to affiliates@fairforecast.com. No cap statement is published, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/true-classic/', 'third_party_directory', 'affiliate_program', 'Published rates conflict across channels: the US program on CJ Affiliate is listed at 10% per sale, while directories separately cite 5%, up to 12% and up to 15%, and the brand''s UK Awin profile pays 20% new / 0.5% existing. No single rate settles across regions, so commission_rate is recorded as null with the conflict documented.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 8, 9, 8, 4, '{"compensation": "Rates conflict by channel and region (20% new / 0.5% existing in the UK Awin profile; 10% listed for US CJ; 5-15% elsewhere), so no rate is recorded and compensation scores low until a channel is chosen; cap unknown.", "contact_access": "A program contact email (affiliates@fairforecast.com) is published on the brand''s Awin profile for questions and custom campaigns.", "credibility": "One of the fastest-growing DTC menswear brands, running staffed programs on CJ and Awin; the rate confusion across channels is the main caveat.", "niche_fit": "Fitted tees and basics are everyday menswear staples that fit fashion, grooming and lifestyle creators, with strong brand recall.", "opportunity_availability": "Joinable through the CJ and Awin network profiles; coupon and discount sites are excluded.", "ugc_evidence": "The Awin profile explicitly recruits bloggers and content creators and supplies campaign assets; no creator counts are published, so saturation stays unknown."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Xero Shoes', 'https://xeroshoes.com', 'Colorado-based maker of barefoot and minimalist footwear - casual shoes, performance trainers, hiking boots and sandals - sold in more than 97 countries. Its affiliate arrangements vary by region: the US program is invite-only through Rakuten Advertising, while the UK/EU program runs on Awin with dynamic commission up to 10%.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'fashion'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Rakuten Advertising', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://marketplace.referly.so/affiliate-programs/xero-shoes.', 'https://marketplace.referly.so/affiliate-programs/xero-shoes', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Xero Shoes Affiliate Program', 'https://marketplace.referly.so/affiliate-programs/xero-shoes', 'https://marketplace.referly.so/affiliate-programs/xero-shoes', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marketplace.referly.so/affiliate-programs/xero-shoes', 'third_party_directory', 'affiliate_program', 'Summary of the brand''s own FAQ: ''the US affiliate program is now invite-only and runs through Rakuten, focused on partners who create consistent, high-quality content. The UK/EU program runs via Awin with dynamic commission up to 10% and a 30-day cookie, and there is a separate Australia/New Zealand application.'' Average order value is around $130-$160.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/xero-shoes/', 'third_party_directory', 'affiliate_program', 'Directory figures conflict with the current regional setup: several list a flat 10% with 60- or 90-day cookies and monthly PayPal payouts from a $20 threshold (an older in-house arrangement), and one lists 4%. Because ''up to 10%'' on Awin is a ceiling rather than a settled rate and the sources disagree, commission_rate is recorded as null and the cap as unknown.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 12, 8, 4, 5, 4, '{"compensation": "Awin advertises dynamic commission up to 10% (a ceiling, not a settled rate) and directories conflict between 4%, 10% and 10-15%, so no rate is recorded; cap unknown.", "contact_access": "No email is published in the sources checked; contact runs through the regional network programs.", "credibility": "One of the best-known barefoot footwear brands, selling in 97+ countries, with region-specific network programs.", "niche_fit": "Barefoot shoes are a passionate niche for running, hiking and foot-health creators, with $130-$160 average orders.", "opportunity_availability": "The US program is invite-only via Rakuten; UK/EU creators can join through Awin and ANZ creators through a regional application, so availability scores low.", "ugc_evidence": "The Rakuten program is explicitly focused on partners who create consistent, high-quality content; no creator counts are published, so saturation stays unknown."}'::jsonb);
