  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Everflow', null, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://organixx.com/influencer/.', 'https://organixx.com/influencer/', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Organixx Influencer Program', 'https://organixx.com/influencer/', 'https://organixx.com/influencer/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://organixx.com/influencer/', 'official_site', 'affiliate', 'Organixx''s official influencer page states the earning structure is flexible (CPA, revenue share, flat fee, or a combination, agreed individually) and says verbatim ''No cap'' and ''no ceiling on earnings''; its FAQ repeats: ''There is no ceiling on performance earnings.'' No fixed percentage rate is published anywhere on the page, so commission_rate is recorded as null rather than guessed. Applications run through Everflow (the page''s Apply button links to organixx.everflowclient.io). The cap is verified uncapped on the brand''s own wording.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://organixx.com/influencer/', 'official_site', 'ugc_collab', 'The same page is a dedicated creator-recruitment page: it targets short-form video creators (Reels, TikTok, Stories) in gut health, hormonal balance, fitness recovery and longevity, offers complimentary products, exclusive audience discount codes and brand-funded ad spend behind creator content, and says the roster is kept tight with every application reviewed by a real person (typical partners 5k-15k followers, no hard minimum).', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 12, 10, 6, 5, '{"niche_fit": "A broad clean-supplement line (magnesium, collagen, probiotics, turmeric) maps directly onto gut-health, hormone, recovery and longevity creator content.", "ugc_evidence": "A dedicated influencer page recruiting short-form video creators, with free product, audience codes and brand-funded ads behind creator content; no creator counts were published on fetched pages.", "compensation": "Earnings are explicitly uncapped on the brand''s own page (''No cap'', ''no ceiling on performance earnings''), but the percentage is agreed individually and unpublished, so the rate is null and compensation is scored mid-range.", "contact_access": "Application is a short form on the official page with a named, dedicated partnership contact promised after acceptance; no public program email is published.", "opportunity_availability": "The roster is deliberately tight and every application is manually reviewed, so availability is scored conservatively.", "credibility": "Founded 2016, ~$30M/year revenue, 22,000+ five-star reviews and published third-party test results, per its own page."}'::jsonb);
