  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Fit ''n Prep Meals Affiliate Program', 'https://fitnprep.com/affiliates', 'https://fitnprep.com/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fitnprep.com/affiliates', 'official_site', 'affiliate', 'Fit ''n Prep''s official affiliate page publishes a 10% commission on the order subtotal (before delivery and tax) with lifetime attribution (''your link never expires''), and its FAQ answers the earnings question verbatim: ''There is no cap on how much you can earn.'' Joining is free and instant - name and email generate a referral link with no approval wait. The cap is verified uncapped on the brand''s own wording.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://fitnprep.com/affiliates', 'official_site', 'ugc_collab', 'The same page explicitly recruits content creators and communities (''Florida food, fitness and family accounts: one link in bio, 10% of everything it brings in'') alongside trainers, gyms and nutritionists, and publishes a contact email and phone number for program questions.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 13, 15, 11, 10, 3, '{"niche_fit": "Macro-labeled chef meals are natural content for meal-prep, fitness-nutrition and busy-family food creators.", "ugc_evidence": "The official page names creators and communities as a target segment with link-in-bio promotion; no creator counts were published on fetched pages.", "compensation": "10% of every order subtotal with a verified ''no cap on how much you can earn'' statement and lifetime attribution on the official page.", "contact_access": "A contact email and phone number for program questions are published directly on the affiliate page.", "opportunity_availability": "Fully open and instant - a referral link is generated immediately with no application or approval wait.", "credibility": "A small regional meal-prep company with a USDA-inspected kitchen; far smaller than national meal-delivery brands, so credibility is scored low."}'::jsonb);
