  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://reddremedies.com/pages/affiliate-tool-kit', 'official_site', 'affiliate', 'Redd Remedies'' official affiliate tool kit page states affiliates receive a unique link plus a 15%-off audience coupon code and earn ''15% commissions on sales from your unique link or with your coupon code'', with a dedicated Affiliate Program Manager reachable at affiliate@reddremedies.com. No cap statement appears anywhere on the fetched page, so the cap is recorded as unknown.', 'verified', now());
