  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 15, 13, 6, 4, '{"niche_fit": "Targeted herbal formulas for stress, sleep, thyroid and joint concerns give wellness creators specific, story-led products to build content around.", "ugc_evidence": "A formal creator program with monthly content deliverables, free monthly product, swipe copy, image assets and repost eligibility, all documented on the official page; no creator counts were published.", "compensation": "15% commission on link and code sales, stated plainly on the official page; no cap statement was published, so the cap stays unknown.", "contact_access": "A named Affiliate Program Manager email (affiliate@reddremedies.com) is published on the official page for questions and collaboration ideas.", "opportunity_availability": "Approval-based with a signed affiliate agreement and monthly contracts, so availability is scored conservatively.", "credibility": "An established family-owned brand headquartered in Bradley, Illinois, with published FDA/FTC compliance rules for affiliates."}'::jsonb);
