  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/perfect-keto/', 'affiliate_directory', 'affiliate', 'Multiple affiliate directories agree the Perfect Keto program pays 15% base commission rising to 20% on performance, with a 30-day cookie and a $50 payout threshold, managed on Refersion (signup portal perfectketo.refersion.com; the brand''s own affiliate page is perfectketo.com/new-affiliate/). The 15% base rate is recorded; no cap statement was found on any fetched page, so the cap is unknown.', 'publicly_reported', now());
