  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 16, 7, 7, 4, '{"niche_fit": "A full keto pantry (ketones, MCT, collagen, bars) is a staple category for low-carb recipe and metabolic-health creators.", "ugc_evidence": "Directories consistently describe creator recruitment with free product, custom codes and milestone bonuses; no creator counts were published on fetched pages.", "compensation": "15% base commission rising to 20% on performance, consistently reported across directories; no cap statement found, so the cap stays unknown.", "contact_access": "Signup runs through the Refersion portal linked from the brand''s own affiliate page; no public program email was published on fetched pages.", "opportunity_availability": "Application required; one directory notes audience-size guidance (5k monthly views or 10k followers), so availability is scored mid-range.", "credibility": "Founded 2016 by a functional-medicine physician and one of the largest dedicated keto brands, per directory coverage."}'::jsonb);
