  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lifeextension.com/aff/faq', 'official_site', 'affiliate', 'Life Extension''s official affiliate FAQ states: ''Life Extension''s Affiliate Program pays affiliates a commission rate of 6% for each sale generated through these affiliate links'', with signup via its CJ (Commission Junction) publisher application, monthly CJ payments, no application fee and no minimum sales quota. Its ''How much can I earn?'' answer gives no cap figure or no-cap statement, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.lifeextension.com/aff/faq', 'official_site', 'ugc_collab', 'The same FAQ says eligibility requires owning a digital property ''such as a website, an email newsletter, or social media channel'' with sufficient audience reach, and that affiliates may reuse the brand''s published articles and product images with attribution - a publisher-leaning program that still admits social creators.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 10, 8, 8, 7, 5, '{"niche_fit": "One of the deepest supplement catalogues available, covering almost every health topic a wellness creator covers.", "ugc_evidence": "The program is framed mainly for websites and newsletters, though social channels qualify; no creator counts or creator-specific perks were published on the fetched page.", "compensation": "6% flat on the official FAQ - below most DTC supplement programs; no cap statement published, so the cap stays unknown.", "contact_access": "Application runs through the CJ publisher signup linked from the official FAQ; no direct program email is published.", "opportunity_availability": "Open application via CJ with an eligibility review of the applicant''s digital property.", "credibility": "A decades-old, nationally known supplement institution with a large research and publishing operation."}'::jsonb);
