  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.truniagen.com/pages/affiliate-program', 'official_site', 'affiliate', 'Tru Niagen''s official affiliate page says partners join ''through our Impact affiliate program'' by submitting an application and earn ''a commission of up to 10% for all sales'', tracked on the Impact dashboard. ''Up to 10%'' is a rate ceiling, not a published base rate, so commission_rate is recorded as null with the ceiling documented here. No cap statement appears on the page, so the cap is unknown.', 'verified', now());
