  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Legion Athletics Affiliate / Ambassador Program (BrandChamp)', 'https://legionathletics.brandchamp.io/apply', 'https://www.healthfitnesscoupon.com/deals/legion-athletics/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.healthfitnesscoupon.com/deals/legion-athletics/', 'affiliate_directory', 'affiliate', 'Legion''s own site footer ''Affiliates'' link leads to a brand-run application at legionathletics.brandchamp.io/apply. Published rates conflict sharply across sources - one directory reports the affiliate page advertising 30%, Lasso lists up to 15%, FlexOffers lists 8% on new-customer and 1.6% on existing-customer sales, and BarBend reports 0.8%-4.8% - so commission_rate is recorded as null with the conflict documented, per the evidence standard. No cap statement was found on any fetched page, so the cap is unknown.', 'publicly_reported', now());
