  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://uppromote.com/affiliate-directory/ryze/', 'affiliate_directory', 'affiliate', 'Directory coverage describes a dual structure: a standard affiliate program via networks (FlexOffers/Sovrn, ~6.4% per FlexOffers with a 30-day cookie) and a Brand Ambassador Program for social influencers. Other third-party posts claim ambassadors earn 15%, which conflicts with the network figure and is not published on a fetched official page, so commission_rate is recorded as null with the conflict documented. No cap statement was found, so the cap is unknown.', 'publicly_reported', now());
