  insert into public.brands (name, website, description, country, status) values ('WiseBond', 'https://www.wisebond.com', 'US epoxy brand selling deep-pour and bar/table-top epoxy resins, colorants, tools and accessories for river tables, countertops and resin art, sold direct through WiseBond.com. Its Influencer Affiliate Program is built specifically for artists, woodworkers, designers and creative studios with a social media presence: creators share a personal discount code and earn cash commission on every referred purchase.', 'United States', 'published') returning id into bid;
