  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Brand direct', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.wisebond.com/pages/affiliates.', 'https://www.wisebond.com/pages/affiliates', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'WiseBond Influencer Affiliate Program — 10% cash commission, no cap on earnings (info@wisebond.com)', 'https://www.wisebond.com/pages/affiliates', 'https://www.wisebond.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wisebond.com/pages/affiliates', 'official_site', 'affiliate', 'Official WiseBond affiliate page fetched in full: ''Refer your followers! Earn a 10% cash commission!'' Affiliates get a personal discount code (followers save 10%), an Affiliate Dashboard with live tracking, and are paid 10% of referral purchases by cash check once they hit $150. The page answers the earnings-cap question directly: ''Is there a cap on earnings? No way'' — and its FAQ (updated October 15, 2026) repeats ''No earnings cap: There''s no limit on how much commission you can earn'' and ''You earn 10% of every qualifying purchase made with your code or link, with no cap on total earnings.'' The explicit no-cap statements on the brand''s own page make the commission cap UNCAPPED.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wisebond.com/pages/affiliates', 'official_site', 'creator_program', 'The same official page is written for creators: ''If you are an artist, creative studio, designer, wood worker, with your own personal or business social media platform, the WiseBond.com affiliate program is for you. We are seeking influencers to partner with us in creating unique and informative content.'' It encourages posting the code across Instagram, YouTube, TikTok, Facebook groups and forums, and publishes info@wisebond.com for affiliate payment questions.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 17, 15, 12, 9, 4, '{"compensation": "10% cash commission with an explicit no-cap statement on the brand''s own page; epoxy project orders often run to several hundred dollars, though payout is by check at a $150 threshold", "contact_access": "Open application form on the brand''s own page plus a published contact email (info@wisebond.com)", "credibility": "Full program FAQ and affiliate code of conduct published on the brand''s own storefront", "niche_fit": "Epoxy river tables, countertops and resin art are a proven, highly visual DIY/maker UGC format", "opportunity_availability": "Free, open sign-up aimed at social media makers of any size", "ugc_evidence": "The program is explicitly an influencer program for content creators, with a personal code designed to be shared in posts and videos"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('MAS Epoxies', 'https://masepoxies.com', 'US epoxy brand (MAS Epoxies, South St Paul, Minnesota) selling epoxy resin systems for woodworking, river tables, boat building and resin art. Its affiliate program is aimed squarely at content creators and its ''MAS Makers'' community: affiliates earn tiered commission through custom coupon codes and tracking links, with homepage maker spotlights and sponsorship opportunities for top partners.', 'United States', 'published') returning id into bid;
