  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'MAS Epoxies Affiliate Program — up to 12% tiered commission, no cap on earnings (hello@masepoxies.com)', 'https://masepoxies.com/pages/affiliates', 'https://masepoxies.com/pages/affiliates', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://masepoxies.com/pages/affiliates', 'official_site', 'affiliate', 'Official MAS Epoxies affiliate page fetched in full: ''Are you a content creator?'' — free to join, monthly payouts via PayPal on or around the 15th, ''Up to 12% Commission'', a custom MAS coupon code, opportunities for MAS sponsorship and homepage Maker Spotlights. The program is tier-driven (the more sales generated, the greater the perks) and tracking links are generated within Everflow. Its FAQ answers the earnings-cap question directly: ''Is there a cap on how much I can earn? There is no cap but you must reach $50 in commission before a payout can occur.'' The explicit no-cap statement on the brand''s own page makes the commission cap UNCAPPED. ''Up to 12%'' is the published ceiling of the tier structure and is recorded as the rate, following the directory''s rate-ceiling convention.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://masepoxies.com/pages/affiliates', 'official_site', 'contact', 'The same official page publishes the brand''s contact details: hello@masepoxies.com and 1-800-755-8568, 275 Bridgepoint Way, South St Paul, MN 55075, plus its Facebook, Instagram, Pinterest and YouTube profiles.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 17, 14, 12, 9, 3, '{"compensation": "Tiered commission up to 12% with an explicit no-cap FAQ answer, monthly PayPal payouts and a $50 threshold; the starting tier is not published", "contact_access": "Open application on the brand''s own page plus a published contact email (hello@masepoxies.com) and phone number", "credibility": "Established US epoxy maker with full program terms published on its own storefront; smaller brand than the category leaders", "niche_fit": "Epoxy woodworking and resin-art projects are a staple maker/DIY UGC format with strong tutorial demand", "opportunity_availability": "Free to join, explicitly open to content creators and influencers", "ugc_evidence": "The page opens with ''Are you a content creator?'', runs a named maker community (MAS Makers) and offers homepage Maker Spotlights and sponsorships"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Stone Coat Countertops', 'https://stonecoatcountertops.com', 'US surface-coatings brand (Kalamazoo, Michigan) selling epoxy and polyaspartic systems for countertops, floors, shower walls and wood projects, built around a large DIY tutorial audience (1.5M+ YouTube subscribers). Its affiliate program gives creators a custom coupon code and tier-based commissions and perks, tracked through Everflow, with sponsorship and maker-spotlight opportunities.', 'United States', 'published') returning id into bid;
