  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Stone Coat Countertops Affiliate Program — tiered commissions via Everflow, no cap on earnings', 'https://stonecoatcountertops.com/pages/epoxy-affiliate', 'https://stonecoatcountertops.com/pages/epoxy-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://stonecoatcountertops.com/pages/epoxy-affiliate', 'official_site', 'affiliate', 'Official Stone Coat Countertops affiliate page fetched in full: ''Join our Stone Coat Epoxy affiliate program to earn rewards for sharing your creativity and content.'' Free to join; affiliates share a custom coupon code and earn commission on every sale, with a tier-based system unlocking extra perks and commissions as code use grows; monthly payouts via PayPal on or around the 15th; tracking links are generated within Everflow (the Apply Now button leads to the program''s Everflow portal). Its FAQ answers the earnings-cap question directly: ''Is there a cap on how much I can earn? There is no cap but you must reach $50 in commission before a payout can occur.'' The explicit no-cap statement on the brand''s own page makes the commission cap UNCAPPED. The page does not publish a percentage rate (tier-based, figures inside the portal), so commission_rate is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://stonecoatcountertops.com/pages/about-us', 'official_site', 'general', 'Stone Coat''s official About page states its products serve DIYers, homeowners and makers as well as contractors, and that its commitment to epoxy creators includes an extensive library of YouTube tutorials (1.5 million+ subscribers), online tutorials and hands-on training — a content-first brand whose affiliate page promises exclusive sponsorship opportunities and maker spotlights on its platforms.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 17, 12, 9, 9, 4, '{"compensation": "Explicit no-cap statement and tiered perks, but the percentage rates are not published outside the affiliate portal, so compensation cannot be graded higher", "contact_access": "Open application from the brand''s own page into its Everflow portal; no public program email published", "credibility": "Large established DIY brand with 1.5M+ YouTube subscribers and full program FAQ on its own site", "niche_fit": "Epoxy countertop and flooring transformations are a core DIY home-improvement UGC format", "opportunity_availability": "Free to join with immediate code-based earning per the official page", "ugc_evidence": "Program copy is creator-first (''sharing your creativity and content''), with sponsorships and maker spotlights showcasing affiliate projects"}'::jsonb);
