  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.airdoctorpro.com/shop/affiliate-program', 'official_site', 'affiliate', 'Official AirDoctor affiliate page fetched in full: ''You will receive 15% commission on all gross sales (unless specified differently in the campaign)''; payouts on or before the 15th of the month via Tipalti for the prior month''s commissions; no fee to join. Commissions are tracked through Everflow, with a private affiliate membership site, dashboard analytics, swipes and graphics. The page makes no statement about an earnings cap, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.airdoctorpro.com/shop/affiliate-program', 'official_site', 'creator_program', 'The same official page''s partner criteria are creator-focused: partners should be passionate about healthy living, able to ''create, educate and share authentic product information editorials, images, and promotions through your platform'', and have ''a strong social engagement and relationship with your follower''s presence''. Paid advertising is permitted with provided ad copy and approved claims, though the brand says organic content in the creator''s own voice performs best.', 'verified', now());
