  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.eufy.com/affiliate', 'official_site', 'affiliate', 'eufy''s official US affiliate page: ''The eufy Affiliate Program invites review sites, online communities, bloggers, and other content website owners to promote products and services on their sites and earn commission on the sales they refer to us.eufy.com.'' Publishers apply, receive links, and can build custom links to any URL on the store through the affiliate networks'' tool suites. The page itself does not publish a commission percentage, and it makes no earnings-cap statement, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/niche/home-security/', 'listing', 'affiliate', 'Lasso''s home-security program roundup lists Eufy Life on Impact at 7%-15% per sale with a 30-day cookie and a $50 payout threshold, while Takeads lists the eufy program at up to 12% per sale and eufy''s own eufyMake storefront promotes ''up to 5% commission''. Because the published figures conflict (5% vs 7%-15% vs up to 12% depending on storefront and source), commission_rate is null with the conflict recorded here; the Impact route and 30-day cookie are consistent.', 'publicly_reported', now());
