  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.whichprogram.com/en/topic/pets', 'listing', 'affiliate', 'WhichProgram''s pet-program index lists Zesty Paws at 10% per sale with a 30-day cookie, application via ShareASale. Because published sources conflict (3% vs 10%), commission_rate is null with the conflict recorded here; the ShareASale route is the one documented by the index. (The brand''s separate TikTok Shop creator activity is not the route recorded here — the directory entry rests on the network program.)', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://career.io/job/dtc-and-social-commerce-manager-zesty-paws-1e7d833a7c2af5bcb2e090d03bb02c80', 'listing', 'creator_program', 'A Zesty Paws job posting for a DTC and Social Commerce Manager states the role will ''Own and scale the affiliate programs for ZestyPaws.com and SolidGoldPet.com from strategy through execution'' and ''Identify, recruit, and manage affiliate partners'' — direct evidence the brand staffs and grows its own DTC affiliate program rather than relying only on marketplace channels.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 8, 8, 8, 4, '{"compensation": "Published rates conflict between 3% and 10% of sale, so no rate can be credited until verified in-network", "contact_access": "Application runs through ShareASale; no public partnerships email found", "credibility": "One of the largest US pet-supplement brands, with a staffed DTC affiliate function", "niche_fit": "Functional pet supplements are a core pet UGC category with strong problem/solution content angles", "opportunity_availability": "Standard network application, no follower minimum published", "ugc_evidence": "The brand employs dedicated staff to recruit and manage affiliate partners for its own storefront program"}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('FitBark', 'https://www.fitbark.com', 'Pet-tech brand selling GPS trackers and research-grade activity and sleep monitors that clip to a dog''s collar, tracking location, activity, rest, calorie burn and health changes through its app. Its affiliate program is administered through ShareASale and welcomes bloggers, trainers, daycares, walkers and veterinarians.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'pets'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'creator_application', null, 'https://help.fitbark.com/en/articles/6492538-affiliate-marketing-program', 'https://help.fitbark.com/en/articles/6492538-affiliate-marketing-program', 'needs_review', null);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'ShareASale', 12, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://help.fitbark.com/en/articles/6492538-affiliate-marketing-program.', 'https://help.fitbark.com/en/articles/6492538-affiliate-marketing-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'FitBark Affiliate Program — 12% starting commission via ShareASale, 60-day cookie', 'https://help.fitbark.com/en/articles/6492538-affiliate-marketing-program', 'https://help.fitbark.com/en/articles/6492538-affiliate-marketing-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://help.fitbark.com/en/articles/6492538-affiliate-marketing-program', 'official_site', 'affiliate', 'FitBark''s official help-center program page (updated September 1, 2025) fetched in full: ''We pay a 12% starting commission rate''; the program is administered by ShareASale (''You must first become a member of the ShareASale Affiliate Network, which is our third party program administrator''); average order size around $100; a cookie tracks referred visitors; no fees and no minimum sales level to remain in the program, with commission paid once earnings reach $50. The page makes no statement about an earnings cap, so the cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://backlinko.com/pet-affiliate-programs', 'listing', 'affiliate', 'Backlinko''s pet-program roundup independently reports FitBark at a 12% starting commission per sale via ShareASale with a 60-day cookie duration and an average order value of $100, consistent with the brand''s own published terms, so 12% is recorded.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 14, 8, 8, 4, '{"compensation": "12% starting commission on ~$100 average orders with a 60-day cookie, and higher rates for volume per roundup reports; no cap statement published", "contact_access": "Application runs through ShareASale; no public partnerships email found", "credibility": "Pioneer pet-wearables brand whose own help center publishes full program terms", "niche_fit": "GPS and activity trackers are demonstrable pet-tech products (escape alerts, activity data, sleep scores)", "opportunity_availability": "Free ShareASale application; the brand welcomes bloggers, trainers, daycares, walkers and vets, and sets no minimum sales level", "ugc_evidence": "Long-running network program aimed at pet bloggers and professionals; no dedicated creator page published"}'::jsonb);
